import Card from "./Card";
import React, { useState } from 'react';

const Cards = (props) => {
  console.log(props.category);
  console.log(props.courses);

  let category = props.category;
  const [likedCourses, setLikedCourses] = useState([]);

  function getCourses() {
    if (!props.courses || Object.keys(props.courses).length === 0) {
      return []; 
    }

    if (category === "All") {
      let allCourses = [];
      Object.values(props.courses).forEach((array) => {
        array.forEach((courseData) => {
          allCourses.push(courseData);
        });
      });
      return allCourses;
    } else {
      return props.courses[category] || []; // Return empty array if category data is undefined
    }
  }

  return (
    <div className="flex flex-wrap justify-center gap-4 mb-4">
      {
        getCourses().map((course) => {
          return <Card course={course} key={course.id} likedCourses={likedCourses} setLikedCourses={setLikedCourses} />; 
          // Corrected `key={course.id}` instead of `key={props.courses.id}`
        })
      }
    </div>
  );
};

export default Cards;
